## Key public interfaces (exact signatures)

```ts
type Result<T> = { ok: true; value: T } | { ok: false; error: UiaFailure };
interface UiaFailure { code: UiaErrorCode; message: string; details?: Record<string, JsonValue>; }

// ---- canonicalization (review point 5) ----
function canonicalize(value: JsonValue): string;   // strict input; unsupported values → CanonicalizationError (programmer-contract error, not a semantic failure)
function sha256Hex(input: Uint8Array): string;
type JsonValue = null | boolean | JsonString | number | JsonValue[] | { [k: string]: JsonValue };

// ---- descriptor hash ----
function descriptorHashInput(d: IdentityVersionDescriptor): JsonValue;        // explicit 8-field projection; throws CanonicalizationError if any field is non-conforming
function descriptorHash(d: IdentityVersionDescriptor): `urn:hash:sha256:${string}`;

// ---- ownership (review point 6) ----
interface ParticipantRecordOwn extends Readonly<ParticipantRecord> {}         // all record types are deep-frozen; constructors copy input
function createParticipantRecord(input: ParticipantRecord): ParticipantRecordOwn;   // same shape for all entity constructors

// ---- temporal context (review point 7) ----
type TemporalBasis = 'ASSERTED_AT' | 'SIGNED_AT' | 'INGESTED_AT' | 'ASSESSED_AT' | 'DECIDED_AT';
interface TemporalContext {
  basis: TemporalBasis;              // which declared timestamp kind governs THIS evaluation (domain policy, §10.2)
  observed: {
    asserted_at?: Timestamp;         // facts of the local record; each is declared, not assumed trusted (§10.1)
    signed_at?: Timestamp;           // trusted only when an applicable trusted-time mechanism exists — the caller asserts that here, spec does not define the mechanism
    ingested_at?: Timestamp;
    assessed_at?: Timestamp;
    decided_at?: Timestamp;
  };
}

// ---- edge-bound assurance (review point 1) ----
interface EdgeRef { child: IdentityVersionID; parent: IdentityVersionID; relation: LineageRelationType; }
function assessEdge(edgeRef: EdgeRef, candidateAssessments: ContinuityAssessment[], policy: Policy, ctx: TemporalContext): ApplicableAssessments; // applicability INSIDE, never inferred from unscoped array
function evaluateAssurance(edgeRef: EdgeRef, applicable: ApplicableAssessments, requirement: ContinuityAssuranceRequirement, policy: Policy, ctx: TemporalContext): AssuranceResult;
  // AssuranceResult = {status:'SATISFIED'} | {status:'UNSATISFIED'; code:'ERR_ASSURANCE_PREDICATE_UNSATISFIED'; missing: string[]; disallowed: string[]} | {status:'CONTESTED'; contestedClaims: string[]} (CONTESTED only via policy-defined conflict predicate — see Ambiguity B-2)

interface Policy {
  trustedAssessorDefault?: DomainID[];   // fallback when req.trusted_assessors is absent
  applicableAssessments?  (edgeRef: EdgeRef, assessments: ContinuityAssessment[], ctx: TemporalContext): ContinuityAssessment[];  // §6.3 #6; default: applicability by subject/relation/parent triple
  conflictPredicate?:     (left: ContinuityAssessment, right: ContinuityAssessment, edgeRef: EdgeRef, ctx: TemporalContext) => boolean;  // UNDEFINED BY DEFAULT — BLOCKED, Ambiguity B-2; library never invents a rule
}
type ApplicableAssessments = { edge: EdgeRef; assessments: Readonly<ContinuityAssessment>[]; unresolved: boolean }; // unresolved=true ⇔ parent outside registry (PARENT_UNRESOLVED)

// ---- traversal engine: three explicit phases (review point 3) ----
interface LineageGraph { nodes: IdentityVersionID[]; edges: Readonly<LineageEdge>[]; unresolvedParents: Readonly<readonly [IdentityVersionID, IdentityVersionID[]][]>; cycles: readonly IdentityVersionID[][] } // sorted; arrays only, no Map/Set
function discoverPaths(graph: LineageGraph, scope: LineageTraversalScope, candidateID: IdentityVersionID, originID: IdentityVersionID): Result<PathSet>;
  // Phase 1: scope-permitted edges only (relations excluded by scope are simply not traversable). No permitted path → {ok:false, code:'ERR_NO_TRAVERSAL_PATH'}. Cycles traversed only as dead ends, never returned as successful paths.
function validatePath(path: Path, policy: Policy, requirement: ContinuityAssuranceRequirement, ctx: TemporalContext): Result<PathValidation>;
  // Phase 2: every edge on the path: assessEdge + evaluateAssurance; missing/disqualified/conflicted (when predicate configured) → ERR_ASSURANCE_PREDICATE_UNSATISFIED with per-edge details
function validateMergeClosure(path: Path, graph: LineageGraph, scope: LineageTraversalScope, policy: Policy, requirement: ContinuityAssuranceRequirement, ctx: TemporalContext): Result<MergeClosureResult>;
  // Phase 3: for every MERGED_FROM node on the path — ALL parent edges (ALL_BRANCHES_MUST_SATISFIED); branch recursion also scope-limited (review point 4); any branch failure → ERR_MERGE_BRANCH_UNSATISFIED with branch details; unvalidated branch is an implementation bug, never a silent pass
function evaluateBinding(graphState: {graph: LineageGraph; descriptors: IdentityVersionDescriptor[]}, binding: ConditionalVersionBinding, candidateID: IdentityVersionID): BindingResult;
  // Orchestrator of the three phases after §8.3 prechecks; BindingResult = {eligible:true; acceptedPaths: Path[]}
  //              | {eligible:false; code:'ERR_AUTHORITY_BINDING_MISMATCH'|'ERR_NO_TRAVERSAL_PATH'|'ERR_MERGE_BRANCH_UNSATISFIED'|'ERR_ASSURANCE_PREDICATE_UNSATISFIED'|'CYCLE_DETECTED'; details}
  // no-path vs merge-closure distinction preserved: ERR_NO_TRAVERSAL_PATH is emitted only by Phase 1, ERR_MERGE_BRANCH_UNSATISFIED only by Phase 3

// ---- credentials (review point 8: rich unions) ----
function evaluateCredentialUsage(cred: CredentialDescriptor, usage: CredentialUsage): UsageResult;
  // UsageResult = {status:'USAGE_ALLOWED'} | {status:'USAGE_DENIED'; reason:'USAGE_NOT_DECLARED'|'CREDENTIAL_ABSENT'} | {status:'USAGE_UNSUPPORTED'; reason:'USAGE_NOT_IN_ENUM'}
type SignatureVerificationOutcome =
  | { verdict: 'VERIFIED' }                                  // cryptographic relation confirmed only (§4.1: proves ownership/intent/authority/runtime/legitimacy of nothing)
  | { verdict: 'INVALID' }                                   // verifier rejects the cryptographic relation
  | { verdict: 'CRYPTO_UNAVAILABLE'; verifierError: string } // verifier itself failed to evaluate
  | { verdict: 'CRYPTO_UNSUPPORTED' };                       // algorithm_family not supported by the verifier
type SignatureClaimResult = {
  claim: 'PARENT_SIGNATURE_MATCH';
  outcome: SignatureVerificationOutcome;       // never collapsed into a boolean
  validity: { historical: 'VALID' | 'CONTESTED_COMPROMISED' | 'INVALID' | 'KEY_LOST_POLICY_REQUIRED' | 'SUSPECTED_COMPROMISE_FLAGGED'; future_authorizable: boolean };  // §4.4.2: two distinct outcomes, both reported
};
interface SignatureVerifier { evaluate(sig: SignatureRecord, cred: CredentialDescriptor): SignatureVerificationOutcome; } // injectable; real crypto out of scope (§14.1)
function evaluateHistoricalSignature(sig: SignatureRecord, cred: CredentialDescriptor, revocation: CredentialRevocationRecord | undefined, policy: SignatureTemporalPolicy, ctx: TemporalContext): SignatureClaimResult;

// ---- acceptance ----
function applyLifecycle(record: LocalAcceptanceRecord, event: LocalAcceptanceLifecycleEvent, previousState: AcceptanceLifecycleState, ctx: TemporalContext, policy?: LifecyclePolicy): Result<AcceptanceLifecycleState>;
```

