// Error model for UIA-CORE-001 Rev 0.3.3.
//
// Normative protocol errors (UiaErrorCode) are kept strictly separate from
// implementation/mechanism errors (ImplementationErrorCode). A Failure is a
// discriminated union so callers can narrow reliably via its `kind` field.

import type { JsonValue } from './primitives.js';

export type UiaErrorCode =
  | 'ERR_INVALID_RELATION'
  | 'ERR_INVALID_CARDINALITY'
  | 'ERR_NO_TRAVERSAL_PATH'
  | 'ERR_MERGE_BRANCH_UNSATISFIED'
  | 'ERR_ASSURANCE_PREDICATE_UNSATISFIED'
  | 'ERR_AUTHORITY_BINDING_MISMATCH'
  | 'CYCLE_DETECTED'
  | 'PARENT_UNRESOLVED';

export type ImplementationErrorCode =
  | 'S_SELECTOR_INCOMPATIBLE_SCHEME'
  | 'E_APPLICABLE_ASSESSMENTS_UNBRANDED'
  | 'E_TEMPORAL_FIELD_REF_INVALID'
  | 'E_CANONICALIZATION_UNSUPPORTED'
  | 'E_OWNERSHIP_UNSUPPORTED'
  | 'E_UNKNOWN_BOUNDARY_REJECTED';

export interface SpecFailure {
  readonly kind: 'SPEC';
  readonly code: UiaErrorCode;
  readonly message: string;
  readonly details?: Readonly<Record<string, JsonValue>>;
}

export interface MechanismFailure {
  readonly kind: 'MECHANISM';
  readonly code: ImplementationErrorCode;
  readonly message: string;
  readonly details?: Readonly<Record<string, JsonValue>>;
}

export type Failure = SpecFailure | MechanismFailure;

export type Result<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly error: Failure };

export function isOk<T>(r: Result<T>): r is { ok: true; value: T } {
  return r.ok === true;
}

export function isFailure<T>(r: Result<T>): r is { ok: false; error: Failure } {
  return r.ok === false;
}

// Canonicalization is out of scope for Task 2 (Task 3). This error type is
// provided here so downstream modules can throw/return it without depending
// on the canonicalizer. It is a mechanism error, never a normative state.
export class CanonicalizationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CanonicalizationError';
  }
}

// Convenience constructors (mechanism failures only at this layer; spec
// failures are constructed by domain modules with their own context).
export function mechanismFailure(code: ImplementationErrorCode, message: string): MechanismFailure {
  return { kind: 'MECHANISM', code, message };
}

export function specFailure(code: UiaErrorCode, message: string): SpecFailure {
  return { kind: 'SPEC', code, message };
}

// Primitive domain types for UIA-CORE-001 Rev 0.3.3.

import type { MechanismFailure, Result } from './errors.js';

// ---------------------------------------------------------------------------
// Branded identifiers (nominally distinct strings)
// ---------------------------------------------------------------------------

type Brand<T, B extends string> = T & { readonly __brand: B };

export type ParticipantID = Brand<string, 'ParticipantID'>;
export type IdentityVersionID = Brand<string, 'IdentityVersionID'>;
export type RuntimeInstanceID = Brand<string, 'RuntimeInstanceID'>;
export type CredentialID = Brand<string, 'CredentialID'>;
export type AssessmentID = Brand<string, 'AssessmentID'>;
export type AcceptanceID = Brand<string, 'AcceptanceID'>;
export type DomainID = Brand<string, 'DomainID'>;

export type Timestamp = number;

// Convenience constructors (identity casts; validation of format is the caller's
// responsibility at the boundary, except where a validator is provided).
export function participantId(value: string): ParticipantID {
  return value as ParticipantID;
}
export function identityVersionId(value: string): IdentityVersionID {
  return value as IdentityVersionID;
}
export function runtimeInstanceId(value: string): RuntimeInstanceID {
  return value as RuntimeInstanceID;
}
export function credentialId(value: string): CredentialID {
  return value as CredentialID;
}
export function assessmentId(value: string): AssessmentID {
  return value as AssessmentID;
}
export function acceptanceId(value: string): AcceptanceID {
  return value as AcceptanceID;
}
export function domainId(value: string): DomainID {
  return value as DomainID;
}

// ---------------------------------------------------------------------------
// Strict JSON value type (data model; runtime enforcement lives in canonical.ts,
// Task 3, but the type is declared here so ownership/canonicalization can share it)
// ---------------------------------------------------------------------------

export type JsonValue =
  | null
  | boolean
  | string
  | number
  | readonly JsonValue[]
  | { readonly [key: string]: JsonValue };

// ---------------------------------------------------------------------------
// Temporal field references
// ---------------------------------------------------------------------------

export type TemporalBasis = 'ASSERTED_AT' | 'SIGNED_AT' | 'INGESTED_AT' | 'ASSESSED_AT' | 'DECIDED_AT';

// The five standard kinds are reserved well-known references. Extension refs are
// arbitrary strings that are validated at runtime. The type allows both, with
// autocomplete for the standard kinds.
export type TemporalFieldRef = TemporalBasis | (string & { readonly __temporalFieldExt?: never });

export const STANDARD_TEMPORAL_FIELDS: readonly TemporalBasis[] = [
  'ASSERTED_AT',
  'SIGNED_AT',
  'INGESTED_AT',
  'ASSESSED_AT',
  'DECIDED_AT',
];

const EXT_REF_REGEX = /^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)*$/;

function hasLoneSurrogate(value: string): boolean {
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff) {
      // high surrogate: must be followed by a low surrogate
      const next = i + 1 < value.length ? value.charCodeAt(i + 1) : 0;
      if (next < 0xdc00 || next > 0xdfff) return true;
      i++; // consume the pair
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      // stray low surrogate
      return true;
    }
  }
  return false;
}

export function validateTemporalFieldRef(value: unknown): Result<TemporalFieldRef> {
  if (typeof value !== 'string' || value.length === 0) {
    return {
      ok: false,
      error: {
        kind: 'MECHANISM',
        code: 'E_TEMPORAL_FIELD_REF_INVALID',
        message: 'TemporalFieldRef must be a non-empty string',
      },
    };
  }
  // No whitespace or control characters.
  if (/\s/.test(value) || /[\u0000-\u001f\u007f]/.test(value)) {
    return {
      ok: false,
      error: {
        kind: 'MECHANISM',
        code: 'E_TEMPORAL_FIELD_REF_INVALID',
        message: 'TemporalFieldRef must not contain whitespace or control characters',
      },
    };
  }
  if (hasLoneSurrogate(value)) {
    return {
      ok: false,
      error: {
        kind: 'MECHANISM',
        code: 'E_TEMPORAL_FIELD_REF_INVALID',
        message: 'TemporalFieldRef must not contain lone surrogates',
      },
    };
  }

  // Standard refs are reserved well-known references.
  if ((STANDARD_TEMPORAL_FIELDS as readonly string[]).includes(value)) {
    return { ok: true, value: value as TemporalBasis };
  }

  // Extension refs must be well-formed and cannot redefine a standard ref
  // (already excluded above, since standard names are handled).
  if (!EXT_REF_REGEX.test(value)) {
    return {
      ok: false,
      error: {
        kind: 'MECHANISM',
        code: 'E_TEMPORAL_FIELD_REF_INVALID',
        message: 'TemporalFieldRef extension must match ^[A-Za-z][A-Za-z0-9_]*(\\.[A-Za-z][A-Za-z0-9_]*)*$',
      },
    };
  }

  return { ok: true, value: value as TemporalFieldRef };
}

// Re-export MechanismFailure type usage is type-only; nothing runtime imported from errors.
export type { MechanismFailure } from './errors.js';

// Ownership and immutability utilities for UIA-CORE-001 Rev 0.3.3.
//
// Global Constraint 5: deep copy on construction, recursive deep freeze,
// reject unsupported structures, unknown-boundary validation helper.

import type { JsonValue, TemporalFieldRef } from './primitives.js';
import type { MechanismFailure, Result } from './errors.js';
import { mechanismFailure } from './errors.js';

export type DeepReadonly<T> = T extends (infer A)[]
  ? readonly DeepReadonly<A>[]
  : T extends object
    ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
    : T;

const OWNERSHIP_UNSUPPORTED = 'E_OWNERSHIP_UNSUPPORTED' as const;
const UNKNOWN_BOUNDARY_REJECTED = 'E_UNKNOWN_BOUNDARY_REJECTED' as const;

function rejectUnsupported(message: string): Result<never> {
  return { ok: false, error: mechanismFailure(OWNERSHIP_UNSUPPORTED, message) };
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && Object.getPrototypeOf(value) === Object.prototype;
}

export function deepCopy<T>(value: T): Result<T> {
  const seen = new WeakSet<object>();

  function copy(input: unknown): Result<unknown> {
    if (input === null) return { ok: true, value: null };
    const t = typeof input;
    if (t === 'undefined' || t === 'string' || t === 'number' || t === 'boolean') {
      return { ok: true, value: input };
    }
    if (t === 'bigint' || t === 'symbol' || t === 'function') {
      return rejectUnsupported(`Unsupported value type: ${t}`);
    }
    if (Array.isArray(input)) {
      if (Object.getPrototypeOf(input) !== Array.prototype) {
        return rejectUnsupported('Array must have Array.prototype');
      }
      const ownKeys = Object.getOwnPropertyNames(input);
      const symbols = Object.getOwnPropertySymbols(input);
      if (symbols.length > 0) {
        return rejectUnsupported('Array must not have symbol-keyed properties');
      }
      for (const key of ownKeys) {
        if (key === 'length') continue;
        if (!/^\d+$/.test(key)) {
          return rejectUnsupported(`Array must not have non-index own property: ${key}`);
        }
      }
      if (seen.has(input)) {
        return rejectUnsupported('Cyclic reference detected');
      }
      seen.add(input);
      const out: unknown[] = [];
      for (let i = 0; i < input.length; i++) {
        const r = copy(input[i]);
        if (!r.ok) {
          seen.delete(input);
          return r;
        }
        out[i] = r.value;
      }
      seen.delete(input);
      return { ok: true, value: out };
    }
    if (isPlainObject(input)) {
      const ownKeys = Object.getOwnPropertyNames(input);
      const symbols = Object.getOwnPropertySymbols(input);
      if (symbols.length > 0) {
        return rejectUnsupported('Object must not have symbol-keyed properties');
      }
      for (const key of ownKeys) {
        const desc = Object.getOwnPropertyDescriptor(input, key);
        if (!desc) continue;
        if (desc.get !== undefined || desc.set !== undefined) {
          return rejectUnsupported(`Accessor property not allowed: ${key}`);
        }
        if (!desc.enumerable) {
          return rejectUnsupported(`Non-enumerable property not allowed: ${key}`);
        }
      }
      if (seen.has(input)) {
        return rejectUnsupported('Cyclic reference detected');
      }
      seen.add(input);
      const out: Record<string, unknown> = {};
      for (const key of ownKeys) {
        const r = copy(input[key]);
        if (!r.ok) {
          seen.delete(input);
          return r;
        }
        out[key] = r.value;
      }
      seen.delete(input);
      return { ok: true, value: out };
    }
    // null handled above; any other object (Date, Map, Set, class instance, null-proto) rejected
    return rejectUnsupported('Unsupported object: prototype must be Object.prototype');
  }

  const result = copy(value);
  if (!result.ok) return result as Result<T>;
  return { ok: true, value: result.value as T };
}

export function deepFreeze<T>(value: T): DeepReadonly<T> {
  if (value === null || typeof value !== 'object') {
    return value as DeepReadonly<T>;
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      deepFreeze(item);
    }
  } else {
    for (const key of Object.keys(value as Record<string, unknown>)) {
      deepFreeze((value as Record<string, unknown>)[key]);
    }
  }
  Object.freeze(value);
  return value as DeepReadonly<T>;
}

export function validateUnknown<T>(value: unknown, guard: (v: unknown) => v is T): Result<T> {
  if (guard(value)) {
    return { ok: true, value };
  }
  return {
    ok: false,
    error: {
      kind: 'MECHANISM',
      code: UNKNOWN_BOUNDARY_REJECTED,
      message: 'Input failed validation at the unknown boundary',
    },
  };
}

// Re-export commonly needed types for convenience (type-only).
export type { JsonValue, TemporalFieldRef } from './primitives.js';

import { test, expect } from 'bun:test';
import {
  UiaErrorCode,
  ImplementationErrorCode,
  SpecFailure,
  MechanismFailure,
  Failure,
  Result,
  isOk,
  isFailure,
  mechanismFailure,
  specFailure,
  CanonicalizationError,
} from '../../src/core/errors.js';
import type { DeepReadonly } from '../../src/core/ownership.js';

// Type-level: UiaErrorCode is the exact 8-code union. We assert assignability by
// constructing a value of each code (compile-time check via tsc).
const NORMATIVE_CODES: readonly UiaErrorCode[] = [
  'ERR_INVALID_RELATION',
  'ERR_INVALID_CARDINALITY',
  'ERR_NO_TRAVERSAL_PATH',
  'ERR_MERGE_BRANCH_UNSATISFIED',
  'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
  'ERR_AUTHORITY_BINDING_MISMATCH',
  'CYCLE_DETECTED',
  'PARENT_UNRESOLVED',
];

test('error model: all eight normative codes are assignable to UiaErrorCode', () => {
  expect(NORMATIVE_CODES.length).toBe(8);
  for (const code of NORMATIVE_CODES) {
    const f: SpecFailure = specFailure(code, 'msg');
    expect(f.kind).toBe('SPEC');
    expect(f.code).toBe(code);
  }
});

test('error model: mechanism codes belong to ImplementationErrorCode, not UiaErrorCode', () => {
  const mech: ImplementationErrorCode = 'S_SELECTOR_INCOMPATIBLE_SCHEME';
  const f: MechanismFailure = mechanismFailure(mech, 'msg');
  expect(f.kind).toBe('MECHANISM');
  expect(f.code).toBe(mech);

  const mech2: ImplementationErrorCode = 'E_APPLICABLE_ASSESSMENTS_UNBRANDED';
  expect(mechanismFailure(mech2, 'msg').code).toBe(mech2);
});

test('error model: Result narrows via discriminant', () => {
  const ok: Result<number> = { ok: true, value: 42 };
  const bad: Result<number> = { ok: false, error: specFailure('CYCLE_DETECTED', 'cycle') };

  if (isOk(ok)) {
    // narrowed
    const v: number = ok.value;
    expect(v).toBe(42);
  } else {
    throw new Error('expected ok');
  }

  if (isFailure(bad)) {
    const e: Failure = bad.error;
    expect(e.kind).toBe('SPEC');
    if (e.kind === 'SPEC') {
      expect(e.code).toBe('CYCLE_DETECTED');
    }
  } else {
    throw new Error('expected failure');
  }
});

test('error model: SpecFailure and MechanismFailure are distinguishable', () => {
  const spec: Failure = specFailure('PARENT_UNRESOLVED', 'unresolved');
  const mech: Failure = mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'unsupported');
  expect(spec.kind).toBe('SPEC');
  expect(mech.kind).toBe('MECHANISM');
  // kind discriminates
  if (spec.kind === 'SPEC') expect(spec.code).toBe('PARENT_UNRESOLVED');
  if (mech.kind === 'MECHANISM') expect(mech.code).toBe('E_OWNERSHIP_UNSUPPORTED');
});

test('error model: CanonicalizationError is an Error subclass', () => {
  const e = new CanonicalizationError('boom');
  expect(e).toBeInstanceOf(Error);
  expect(e.name).toBe('CanonicalizationError');
  expect(e.message).toBe('boom');
});

// Type-level: DeepReadonly is exported and assignable (compile-time check).
const _deepReadonlyCheck: DeepReadonly<{ a: { b: number[] } }> = { a: { b: [1, 2] } };
void _deepReadonlyCheck;

import { test, expect } from 'bun:test';
import { deepCopy, deepFreeze, validateUnknown } from '../../src/core/ownership.js';
import type { DeepReadonly } from '../../src/core/ownership.js';

test('ownership: deep copy is structurally equal', () => {
  const src = { a: { b: [1, 2, { c: 3 }] }, d: 'x' };
  const r = deepCopy(src);
  expect(r.ok).toBe(true);
  if (r.ok) {
    expect(r.value).toEqual(src);
  }
});

test('ownership: deep copy is reference-disjoint at every level', () => {
  const inner = { c: 3 };
  const src = { a: { b: [1, 2, inner] } };
  const r = deepCopy(src);
  expect(r.ok).toBe(true);
  if (r.ok) {
    expect(r.value).not.toBe(src);
    expect(r.value.a).not.toBe(src.a);
    expect(r.value.a.b).not.toBe(src.a.b);
    expect(r.value.a.b[2]).not.toBe(src.a.b[2]);
  }
});

test('ownership: mutating original after copy does not affect copy', () => {
  const src: { a: { b: number[] } } = { a: { b: [1, 2] } };
  const r = deepCopy(src);
  expect(r.ok).toBe(true);
  if (r.ok) {
    src.a.b.push(999);
    src.a = { b: [0] };
    expect(r.value.a.b).toEqual([1, 2]);
  }
});

