![security-high](https://www.gstatic.com/codereviewagent/security-high-priority.svg) ![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

The current implementation of `validateJsonValue` has three critical issues:
1. **Stack Overflow / Denial of Service**: It recursively validates nested structures without tracking seen objects, which will cause a stack overflow and crash the process if a cyclic structure is passed.
2. **Unsafe Getter Invocation**: It iterates over `Object.keys(value)` and accesses `value[key]` before validating property descriptors. If an object has an enumerable getter, it will be executed before validation, which can lead to side effects or unexpected errors.
3. **Loose Array Property Validation**: It does not strictly validate that array own properties are within the dense index range, allowing extra properties to bypass validation and be silently dropped.

Using an internal recursive helper with a `WeakSet` and validating descriptors before accessing properties resolves all of these issues.

```typescript
export function validateJsonValue(value: unknown): Result<JsonValue> {
  const seen = new WeakSet<object>();

  function validate(val: unknown): Result<JsonValue> {
    if (val === null) return { ok: true, value: null };
    const t = typeof val;
    if (t === 'boolean') return { ok: true, value: val as boolean };
    if (t === 'string') return { ok: true, value: val as string };
    if (t === 'number') {
      const n = val as number;
      if (!Number.isFinite(n)) {
        return {
          ok: false,
          error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'JsonValue number must be finite'),
        };
      }
      return { ok: true, value: n };
    }
    if (Array.isArray(val)) {
      if (Object.getPrototypeOf(val) !== Array.prototype) {
        return {
          ok: false,
          error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'JsonValue array must have Array.prototype'),
        };
      }
      if (seen.has(val)) {
        return {
          ok: false,
          error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'Cyclic reference detected in JsonValue'),
        };
      }
      seen.add(val);
      const out: JsonValue[] = [];
      for (let i = 0; i < val.length; i++) {
        const desc = Object.getOwnPropertyDescriptor(val, String(i));
        if (!desc || desc.get !== undefined || desc.set !== undefined || !desc.enumerable) {
          seen.delete(val);
          return {
            ok: false,
            error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'JsonValue sparse/invalid array at index ' + i),
          };
        }
        const r = validate(val[i]);
        if (!r.ok) {
          seen.delete(val);
          return r as Result<JsonValue>;
        }
        out.push(r.value);
      }
      for (const key of Object.getOwnPropertyNames(val)) {
        if (key === 'length') continue;
        const num = Number(key);
        if (!/^\d+$/.test(key) || String(num) !== key || num >= val.length) {
          seen.delete(val);
          return {
            ok: false,
            error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'JsonValue array must not have extra property: ' + key),
          };
        }
      }
      if (Object.getOwnPropertySymbols(val).length > 0) {
        seen.delete(val);
        return {
          ok: false,
          error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'JsonValue array must not have symbol properties'),
        };
      }
      seen.delete(val);
      return { ok: true, value: out };
    }
    if (isPlainObject(val)) {
      if (seen.has(val)) {
        return {
          ok: false,
          error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'Cyclic reference detected in JsonValue'),
        };
      }
      seen.add(val);
      const ownKeys = Object.getOwnPropertyNames(val);
      for (const key of ownKeys) {
        const desc = Object.getOwnPropertyDescriptor(val, key);
        if (!desc || desc.get !== undefined || desc.set !== undefined || !desc.enumerable) {
          seen.delete(val);
          return {
            ok: false,
            error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'JsonValue object has invalid property: ' + key),
          };
        }
      }
      if (Object.getOwnPropertySymbols(val).length > 0) {
        seen.delete(val);
        return {
          ok: false,
          error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'JsonValue object must not have symbol properties'),
        };
      }
      const out: { [key: string]: JsonValue } = {};
      for (const key of ownKeys) {
        const r = validate(val[key]);
        if (!r.ok) {
          seen.delete(val);
          return r as Result<JsonValue>;
        }
        out[key] = r.value;
      }
      seen.delete(val);
      return { ok: true, value: out };
    }
    return {
      ok: false,
      error: mechanismFailure('E_OWNERSHIP_UNSUPPORTED', 'Unsupported JsonValue type: ' + typeof val)
    };
  }

  return validate(value);
}
